<?php require_once __DIR__ . '/../includes/config.php'; require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/layout.php'; require_login(); if($_SERVER['REQUEST_METHOD']==='POST'){ if(isset($_POST['code'])) $pdo->prepare('INSERT INTO students (code,name,class_id,bus_id) VALUES (?,?,?,?)')->execute([trim($_POST['code']),trim($_POST['name']),(int)$_POST['class_id'],(int)($_POST['bus_id']?:0)?:null]); if(!empty($_FILES['csv']['tmp_name'])){$f=fopen($_FILES['csv']['tmp_name'],'r');while(($r=fgetcsv($f))!==false){if(count($r)>=4)$pdo->prepare('INSERT IGNORE INTO students (code,name,class_id,bus_id) VALUES (?,?,?,?)')->execute([$r[0],$r[1],(int)$r[2],$r[3]===''?null:(int)$r[3]]);}fclose($f);} }
$classes=$pdo->query('SELECT * FROM classes')->fetchAll(); $buses=$pdo->query('SELECT * FROM buses')->fetchAll(); $rows=$pdo->query('SELECT s.*,c.name class_name,b.name bus_name FROM students s LEFT JOIN classes c ON c.id=s.class_id LEFT JOIN buses b ON b.id=s.bus_id ORDER BY s.name')->fetchAll(); ui_start('Students');?>
<div class="card"><h2>Students</h2><form method="post" class="grid"><input name="code" placeholder="Code" required><input name="name" placeholder="Name" required><select name="class_id"><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach;?></select><select name="bus_id"><option value="">No bus</option><?php foreach($buses as $b):?><option value="<?=$b['id']?>"><?=h($b['name'])?></option><?php endforeach;?></select><button class="btn">Add Student</button></form><form method="post" enctype="multipart/form-data" class="grid"><input type="file" name="csv" accept=".csv" required><button class="btn">Import Students CSV</button></form><table><tr><th>Code</th><th>Name</th><th>Class</th><th>Bus</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['code'])?></td><td><?=h($r['name'])?></td><td><?=h($r['class_name'])?></td><td><?=h($r['bus_name']??'No bus')?></td></tr><?php endforeach;?></table></div><?php ui_end(); ?>
